const __pageData = JSON.parse('{"title":"Dealing With Market Uncertainty","description":"","frontmatter":{"title":"Dealing With Market Uncertainty","author":{"name":"Yogesh Patil"},"date":"2025-09-07T00:00:00.000Z","category":"trading-process-and-strategy","sidebar":true,"outline":"deep","prev":{"text":"Trading Psychology – Doubt","link":"/post/trader/trading-psychology-doubt"},"next":{"text":"Stop Losses – My Biggest Downfall","link":"/post/trading-process-and-strategy/stop-losses-my-biggest-downfall"},"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Dealing With Market Uncertainty"}],["meta",{"property":"og:description","content":"The nature of the markets is uncertainty. Human beings do not like uncertainty."}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"post/trading-process-and-strategy/dealing-with-market-uncertainty.md","filePath":"post/trading-process-and-strategy/dealing-with-market-uncertainty.md"}');
